import re
import html

def vis_count(raw):
    decoded = html.unescape(raw)
    stripped = re.sub(r'<[^>]+>', ' ', decoded)
    stripped = stripped.replace('\n', ' ').replace('\t', ' ')
    stripped = re.sub(r'\s+', ' ', stripped).strip()
    return len(stripped), stripped

